// ../runtime/dist/sealife/register.js
function registerSeaLife() {
  for (const kind of Object.keys(SEALIFE_MATERIALS))
    registerGeneratorMaterial(SEALIFE_MATERIALS[kind], () => createSeaMaterial(SEALIFE_MATERIAL_OPTIONS[kind]));
  registerGenerator(STARFISH_GENERATOR, starfishGenerator);
  registerGenerator(CLAM_GENERATOR, clamGenerator);
  registerGenerator(SHELL_GENERATOR, shellGenerator);
}

// ../runtime/dist/index.js
registerSeaLife();

// src/runtime.ts
async function previewWorld(session2, container, options = {}) {
  return createRuntime({
    ...options,
    container,
    world: session2.world,
    terrainChunks: session2.terrainChunks,
    fetchPackage: options.fetchPackage ?? ((id) => session2.itemPackage(id)),
    // A viewer is read-only. All edits use the session tools/commands, followed by a fresh preview.
    editable: false,
    viewOnly: true
  });
}

// demo/app.ts
var byId6 = (id) => document.getElementById(id);
